<section class="panel"><h2>Directorio de acceso</h2><p class="text-secondary">ADMIN administra el sistema; OPERADOR registra operaciones; CONSULTA visualiza y exporta.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['email']) ?></td><td><span class="soft-badge"><?= e($r['role']) ?></span></td><td><?= $r['active']?'Activo':'Desactivado' ?></td><td><?php if((int)$r['id']!==(int)$_SESSION['user']['id']): ?><form method="post" action="<?= e(url('user-toggle')) ?>" data-confirm="¿Cambiar el acceso de este usuario? Se revocarán sus sesiones."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($r['id']) ?>"><button class="btn btn-sm btn-outline-secondary"><?= $r['active']?'Desactivar':'Activar' ?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section><section class="panel mt-4"><h2>Crear usuario</h2><form method="post" action="<?= e(url('user-save')) ?>"><?= csrf_field() ?><div class="row g-3 mt-1"><?php foreach(['name'=>['Nombre','text',100],'email'=>['Correo','email',150],'password'=>['Contraseña (12 a 72 caracteres)','password',72]] as $field=>[$label,$type,$max]): ?><div class="col-md-4"><label for="<?= $field ?>" class="form-label"><?= $label ?></label><input class="form-control" id="<?= $field ?>" name="<?= $field ?>" type="<?= $type ?>" maxlength="<?= $max ?>" required <?= $field==='password'?'minlength="12" autocomplete="new-password"':'' ?>></div><?php endforeach ?><div class="col-md-4"><label for="role" class="form-label">Rol</label><select id="role" name="role" class="form-select"><?php foreach(['CONSULTA','OPERADOR','ADMIN'] as $role): ?><option><?= $role ?></option><?php endforeach ?></select></div></div><button class="btn btn-primary mt-3">Crear usuario</button></form></section>
